/* Correctly rounded j0, j1, y0, y1, jn and yn for a fixed set of inputs, from
   MPFR via gen/gen-bessel-ref.c -- see gen/README.md.  MPFR and not CORE-MATH,
   which has no Bessel functions, and not another libc either: glibc and musl
   both ship the same fdlibm code we do, so there was nothing to compare
   against until now.

   The points are not filtered.  Measuring these functions in ulp of their own
   result would say nothing near a zero -- at the first zero of j0 the correctly
   rounded value is -6.1e-17 and fdlibm is four hundred million million
   representable values away, as would be anything that does not carry extra
   precision there -- so tst-bessel-ulp.c measures against the local scale
   instead.  Every point stays, and a real defect still shows.

   jn and yn are built by recurrence from j0/j1 and y0/y1, so an error in those
   two shows in the recurrence and nowhere else.  A third of their points
   therefore sit on and just beside the first eight zeros of j0 and j1, for
   every order.  Without that block the set walked straight past the defect
   described in tst-bessel-ulp.c.  */

